function queueOps(ops) {
  const inbox = []
  const outbox = []
  const out = []
  const refill = () => {
    if (outbox.length === 0) {
      while (inbox.length > 0) outbox.push(inbox.pop())
    }
  }
  for (const op of ops) {
    if (op[0] === 'push') {
      inbox.push(op[1])
    } else if (op[0] === 'pop') {
      refill()
      out.push(outbox.pop())
    } else if (op[0] === 'peek') {
      refill()
      out.push(outbox[outbox.length - 1])
    } else {
      out.push(inbox.length === 0 && outbox.length === 0)
    }
  }
  return out
}

