def queue_ops(ops):
    inbox, outbox = [], []
    out = []

    def refill():
        if not outbox:
            while inbox:
                outbox.append(inbox.pop())

    for op in ops:
        if op[0] == "push":
            inbox.append(op[1])
        elif op[0] == "pop":
            refill()
            out.append(outbox.pop())
        elif op[0] == "peek":
            refill()
            out.append(outbox[-1])
        else:
            out.append(not inbox and not outbox)
    return out
